import {money} from './data.js';
import {esc,icon} from './ui.js';
export function goalProgress(account,trades,referenceDate=new Date().toISOString().slice(0,10)){
 const goal=account.goal;if(!goal)return null;const rows=trades.filter(t=>t.accountId===account.id),net=rows.reduce((sum,t)=>sum+Number(t.pnl)-Number(t.fees),0),balance=Number(account.balance)+net,profit=balance-goal.initialBalance;
 const stage=Math.max(0,Math.floor((profit+1e-8)/goal.stepProfit)),complete=balance>=goal.targetBalance,risk=goal.baseRisk*Math.pow(goal.multiplier,stage);
 const monday=new Date(referenceDate+'T12:00:00Z');monday.setUTCDate(monday.getUTCDate()-(monday.getUTCDay()+6)%7);const start=monday.toISOString().slice(0,10);const endDate=new Date(monday);endDate.setUTCDate(endDate.getUTCDate()+7);const end=endDate.toISOString().slice(0,10);
 const thisWeek=rows.filter(t=>{const d=(t.openTime||t.date).slice(0,10);return d>=start&&d<end;}),graded=rows.filter(t=>t.grade),aPlus=graded.filter(t=>t.grade==='A+');
 const milestones=[];for(let threshold=goal.initialBalance,index=0;threshold<goal.targetBalance&&index<30;threshold=goal.initialBalance+(++index)*goal.stepProfit){const plannedRisk=goal.baseRisk*Math.pow(goal.multiplier,index);milestones.push({balance:threshold,profit:threshold-goal.initialBalance,risk:plannedRisk,active:index===stage,exceedsCapital:plannedRisk>=threshold});}
 return {balance,profit,risk,stage,complete,riskPercent:balance>0?risk/balance*100:null,progress:Math.max(0,Math.min(100,(balance-goal.initialBalance)/(goal.targetBalance-goal.initialBalance)*100)),remaining:Math.max(0,goal.targetBalance-balance),nextMilestone:Math.min(goal.targetBalance,goal.initialBalance+(stage+1)*goal.stepProfit),weekCount:thisWeek.length,weeklyTradeLimit:goal.weeklyTradeLimit,graded:graded.length,aPlus:aPlus.length,exceedsCapital:risk>=balance,milestones};
}
export function goalCard(account,trades,referenceDate){const g=goalProgress(account,trades,referenceDate),goal=account.goal;if(!g)return '';return `<section class="compounding-card" aria-label="${esc(account.name)} compounding plan"><div class="compounding-top"><div><span class="eyebrow">ONE A+ TRADE. ONE INTENTIONAL WEEK.</span><h2>${esc(account.name)}<span>.</span></h2><p>From ${money(goal.initialBalance)} to ${money(goal.targetBalance)}. Your rules, in focus.</p></div><span class="goal-tag">${icon('target')}${g.complete?'Target reached':'COMPOUNDING GOAL'}</span></div><div class="goal-balance-row"><div><span>Closed-trade balance</span><strong>${money(g.balance)}</strong></div><div class="goal-target"><span>Target balance</span><strong>${money(goal.targetBalance)}</strong></div></div><div class="goal-progress-track" role="progressbar" aria-label="Compounding target progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${g.progress.toFixed(1)}"><i style="width:${g.progress}%"></i></div><div class="goal-progress-caption"><span>${g.progress.toFixed(1)}% of the journey</span><span>${money(g.remaining)} to target</span></div><div class="goal-rule-grid"><div><span>Planned risk / trade</span><strong>${g.complete?'Goal complete':money(g.risk)}</strong><small>${g.complete?'Review your plan before continuing':g.riskPercent===null?'No positive closed balance':g.riskPercent.toFixed(2)+'% of closed balance'}</small></div><div><span>This week</span><strong>${g.weekCount}<em> / ${goal.weeklyTradeLimit} trade</em></strong><small>${g.weekCount>goal.weeklyTradeLimit?'Weekly plan exceeded':g.weekCount===goal.weeklyTradeLimit?'Weekly plan used':'Waiting for your A+ opportunity'}</small></div><div><span>Setup quality</span><strong>${esc(goal.requiredGrade)} only</strong><small>${g.graded?g.aPlus+' / '+g.graded+' reviewed trades graded A+':'No graded executions yet'}</small></div><div><span>Next profit milestone</span><strong>${g.complete?'Reached':money(g.nextMilestone)}</strong><small>Risk doubles after each ${money(goal.stepProfit)} net profit</small></div></div><details class="goal-ladder"><summary>View your risk milestones ${icon('down')}</summary><p class="goal-basis">Milestones count profit above your ${money(goal.initialBalance)} starting balance. Planned risk follows the current closed-trade balance, so it steps down if the balance falls below a milestone.</p><div class="table-scroll"><table><thead><tr><th>Balance milestone</th><th>Net profit</th><th>Risk per trade</th><th>Risk / balance</th></tr></thead><tbody>${g.milestones.map(m=>`<tr class="${m.active?'current-goal-stage':''}"><td>${money(m.balance)} ${m.active?'<span class="badge neutral">Current</span>':''}</td><td>${money(m.profit)}</td><td>${money(m.risk)}</td><td class="${m.exceedsCapital?'negative-text':''}">${(m.risk/m.balance*100).toFixed(2)}%${m.exceedsCapital?' · exceeds capital':''}</td></tr>`).join('')}<tr><td>${money(goal.targetBalance)}</td><td>${money(goal.targetBalance-goal.initialBalance)}</td><td colspan="2">Target reached · review the plan</td></tr></tbody></table></div></details><p class="goal-note">${icon('shield')} Your review plan only. Structure does not place trades or enforce broker risk.${g.exceedsCapital&&!g.complete?' <strong>The planned risk is at or above this account’s balance.</strong>':''}</p></section>`;}
